const enfermedadData=[{"disease":"La ficha salió con la letra encogida y con un hueco enorme abajo","characteristic":"El alto útil de la hoja se calculó en vez de medirse","opts":["El alto útil de la hoja se calculó en vez de medirse","La impresora estaba mal configurada","Se escribió demasiado texto","El papel no era tamaño carta"]},{"disease":"La constancia felicitaba por completar una etapa que no era","characteristic":"Se copió el molde sin leer los rótulos que no dan error","opts":["Se copió el molde sin leer los rótulos que no dan error","Se equivocó el número en el catálogo","La misión cambió de etapa después","Faltaba una traducción"]},{"disease":"La casa parecía cerrada y entraba cualquiera que se registrara","characteristic":"Se leyó el nombre de la regla y no lo que hacía","opts":["Se leyó el nombre de la regla y no lo que hacía","La base de datos estaba mal instalada","Faltaba una contraseña","El servidor estaba caído"]},{"disease":"Las comprobaciones salían en verde y la puerta seguía abierta","characteristic":"Nunca se vio fallar ninguna: avisaban pero no detenían nada","opts":["Nunca se vio fallar ninguna: avisaban pero no detenían nada","Se ejecutaron pocas veces","Estaban escritas en otro idioma","Faltaba una comprobación más"]},{"disease":"Una herramienta arregló un banco y cambió las veintiuna misiones","characteristic":"Se leyó su informe en vez de la lista de archivos que tocó","opts":["Se leyó su informe en vez de la lista de archivos que tocó","La herramienta tenía un error","Se ejecutó dos veces seguidas","Faltaba hacer una copia"]},{"disease":"El correo salió con un compromiso que nadie había decidido","characteristic":"No se buscaron los verbos que comprometen antes de enviarlo","opts":["No se buscaron los verbos que comprometen antes de enviarlo","El correo era demasiado largo","Se envió a la persona equivocada","Faltaba la firma al pie"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

