const identifyTaskDB=[{"s":"La continuación más plausible, que no siempre es la verdadera.","type":"Texto probable"},{"s":"La cifra verosímil y la cita con autor y año que no existen.","type":"Dato falso bien escrito"},{"s":"Un rasgo del estilo que no dice nada sobre la certeza.","type":"El tono seguro"},{"s":"Comprobar contra una fuente que no produjo la afirmación.","type":"Comprobar por fuera"},{"s":"Preguntarle a la misma máquina si tiene razón.","type":"Verificación falsa"},{"s":"La tendencia a darte la razón cuando insistes.","type":"La complacencia"},{"s":"El error que consiste en lo que no se dijo.","type":"La omisión"},{"s":"Qué pasa si ese dato está mal.","type":"El riesgo"},{"s":"El documento original, no quien lo cuenta.","type":"Fuente primaria"},{"s":"Quien entrega, responde por lo entregado.","type":"La firma"}];
const classifyTaskDB=[{"w":"El artículo 123 de la Constitución","gen":"Contenido","n":"Se puede abrir y mirar","g":"Dato comprobable","t":"Existe o no existe"},{"w":"Que la introducción quede cálida","gen":"Contenido","n":"No se puede abrir","g":"Estilo u opinión","t":"Se discute, no se comprueba"},{"w":"La fecha de cierre de inscripciones","gen":"Contenido","n":"Se puede abrir y mirar","g":"Dato comprobable","t":"Existe o no existe"},{"w":"El emoji del título","gen":"Contenido","n":"No se puede abrir","g":"Estilo u opinión","t":"Se discute, no se comprueba"},{"w":"Abrir el texto oficial","gen":"Método","n":"Fuente independiente","g":"Verificación real","t":"No depende de la máquina"},{"w":"Preguntarle «¿estás seguro?»","gen":"Método","n":"La misma fuente","g":"Verificación falsa","t":"Es otra predicción"},{"w":"Una cifra en una ficha de 300 copias","gen":"Riesgo","n":"Sale de casa impresa","g":"Riesgo alto","t":"Se comprueba una por una"},{"w":"El título de un párrafo de adorno","gen":"Riesgo","n":"No decide nada","g":"Riesgo bajo","t":"Se lee y basta"},{"w":"Redactar un primer borrador","gen":"Delegación","n":"Se revisa después","g":"Se le puede pedir","t":"La persona sigue decidiendo"},{"w":"Firmar la entrega","gen":"Delegación","n":"Nadie más responde","g":"No se delega jamás","t":"Quien entrega, responde"}];
const completeTaskDB=[{"s":"El modelo produce texto ___, no texto verdadero.","opts":["probable","revisado","oficial"],"ans":"probable"},{"s":"El error peligroso es el dato falso bien ___.","opts":["escrito","guardado","traducido"],"ans":"escrito"},{"s":"Comprobar por fuera es abrir una fuente ___.","opts":["independiente","parecida","reciente"],"ans":"independiente"},{"s":"Lo que decide cuánto verificar es el ___.","opts":["riesgo","tiempo","tamano"],"ans":"riesgo"},{"s":"El error que consiste en lo que no se dijo es la ___.","opts":["omision","cita","logica"],"ans":"omision"},{"s":"Preguntarle si está seguro produce otra ___.","opts":["prediccion","fuente","prueba"],"ans":"prediccion"},{"s":"Quien entrega, ___.","opts":["firma","espera","consulta"],"ans":"firma"},{"s":"Un cálculo no es una ___.","opts":["medicion","opinion","prueba"],"ans":"medicion"}];
const explainQuestions=[{"q":"Explica por qué el tono seguro de una respuesta no dice nada sobre si es cierta.","ans":"Porque el modelo produce la continuación más probable del texto, y para él un dato que le consta y uno que completó son lo mismo: texto plausible. La seguridad con la que algo está redactado es un rasgo del estilo, no una medida de certeza, y la máquina no tiene forma de saber que no sabe. De ahí sale el error peligroso de esta etapa, que no es el disparate (ese se ve de lejos y se borra) sino el dato falso bien escrito: la cifra verosímil, la cita con autor y año, el artículo de ley con su número. Está redactado exactamente igual que lo cierto, así que nada dentro de la respuesta avisa, y por eso llega hasta la imprenta."},{"q":"¿Qué es comprobar por fuera y por qué no vale preguntarle a la misma máquina?","ans":"Comprobar por fuera es contrastar la afirmación contra algo que no la produjo: el texto oficial, la página del organismo, el archivo del proyecto, el código ejecutándose con el caso real. Vale precisamente porque no depende de quien hizo la afirmación. Preguntarle a la misma máquina «¿estás seguro?» o «dame la fuente» no es una verificación: es pedirle otra predicción, y si inventó un artículo puede inventar igual de bien el enlace que lo respalda. Hay además un problema peor, que es la complacencia: la máquina tiende a darte la razón y, si insistes, cambia de opinión. Así que insistir no acerca a la verdad, solo mueve la respuesta hacia lo que pareces querer oír."},{"q":"Explica la escala de riesgo y por qué no se verifica todo igual.","ans":"Porque verificar cuesta tiempo, que es el gasto más grande del proyecto, así que hace falta un criterio para repartirlo. El criterio no es lo raro que suene la respuesta, sino qué pasa si está mal. Riesgo bajo son los títulos, los emojis y la redacción de adorno: se leen enteros y basta. Riesgo medio es un texto explicativo o un correo interno: se leen los datos y se comprueba lo que se afirma. Riesgo alto es una cifra, una cita o una ley que va a una ficha impresa: fuente primaria, una por una. Y riesgo muy alto es el código que se sube y cualquier compromiso por escrito con alguien de fuera: se prueba el caso real y lo revisa una segunda persona."},{"q":"¿Por qué la omisión es el error más difícil de encontrar? Da el ejemplo del reglamento.","ans":"Porque no está en la respuesta: consiste justamente en lo que no está. Los otros errores (el dato inventado, la fuente falsa, la lógica que no cierra) se pueden buscar leyendo con atención lo que hay escrito. La omisión solo la ve quien sabe qué tendría que estar. El ejemplo de esta casa es el resumen del reglamento de un concurso: era correcto, ordenado y claro, y no decía ni una mentira. Lo que pasaba es que no mencionaba la fecha de cierre de inscripciones, que estaba en una nota al pie del original. Contra un resumen solo hay una defensa: abrir el original y leer al menos los encabezados y las notas, buscando lo que falta."},{"q":"Cuenta el caso de los 226 milímetros y di qué regla dejó escrita.","ans":"Para saber cuánto texto cabe en una hoja carta se calculó el alto útil en vez de medirlo: 279,4 milímetros menos una pulgada por lado, o sea 226. El razonamiento era correcto, pero esa pulgada es el margen por defecto de Chrome y no el que declara la hoja de F.A.R.O, que son 11 milímetros. El alto real era 252. Como consecuencia se desperdiciaban 26 milímetros en cada página y se encogió la letra a 9,5 puntos para que cupiera algo que ya cabía, y costó dos vueltas enteras de trabajo. La regla que quedó escrita en la norma 6 es que un cálculo no es una medición: lo que se puede medir, se mide, y en el caso de las fichas el PDF es el único juez."},{"q":"¿Qué significa que quien entrega firma, y qué se hace con un texto que va hacia fuera?","ans":"Significa que la responsabilidad no se puede repartir con la máquina. Ella no tiene trabajo que perder, ni una maestra enfrente, ni un nombre en el pie de la ficha; la persona que pega el texto, sí. «Lo dijo la IA» no es una defensa ante una maestra, ni ante una institución, ni en la mesa de esta casa. Con un texto que va hacia fuera el método es concreto: se lee entero en voz alta, que es donde se oyen las promesas; se subrayan los verbos que comprometen (acompañamos, garantizamos, entregamos, capacitamos); se comprueba uno por uno si el proyecto puede cumplirlos hoy; se quitan los que no; y se guarda la versión enviada con la fecha y quién la revisó. Cada verbo de esos es una promesa que alguien va a cobrar."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

