function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Para saber cuánto texto cabe en una hoja carta se calculó el alto útil en vez de medirlo: 279,4 milímetros menos una pulgada por lado, o sea 226. Esa pulgada es el margen por defecto del navegador, no el que declara la hoja del proyecto."},{"txt":"Cada misión se construye copiando la anterior. En el molde había una constancia que felicitaba por completar «la Etapa 1», y viajó de misión en misión junto con otros cinco rótulos heredados."},{"txt":"Una regla de seguridad de la base de datos, revisada y aprobada, decía «using (true)». Tenía la forma de una protección y dejaba entrar a cualquiera que se registrara en el proyecto."},{"txt":"Tres comprobaciones escritas para confirmar que la casa estaba cerrada se ejecutaban y salían siempre en verde. Estaban escritas de forma que avisaban pero nunca detenían nada."},{"txt":"Una herramienta reparte las respuestas correctas del quiz entre las cuatro letras y funciona bien. Su informe sale en verde, y de una pasada reescribe las veintiuna misiones del proyecto, incluidas las que ya estaban bien."},{"txt":"La máquina devuelve la introducción de una ficha de Estudios Sociales: tres párrafos claros y una cita de un artículo de la Constitución con número y texto entre comillas. La ficha va a trescientas copias en tres escuelas."},{"txt":"Se le pide resumir el reglamento de un concurso al que M.E.T.A.S quiere presentar el Campeonísimo. El resumen es correcto, ordenado y claro, y no menciona la fecha de cierre de inscripciones, que estaba en una nota al pie."},{"txt":"Se le pide redactar el correo de presentación del proyecto a una Secretaría. Sale un texto excelente que dice que el proyecto «acompaña a los centros durante todo el año escolar». Nadie ha decidido eso."}];
const critCaseQuestions=["1. ¿Qué se puede comprobar aquí, y contra qué exactamente?","2. ¿Qué riesgo tiene si está mal: qué pasa y a quién le pasa?","3. ¿Qué falta, o qué no se está mirando por estar mirando otra cosa?","4. Escribe en 3-4 frases qué harías antes de entregar, y qué firmarías."];
const critCaseGuides=["Lo comprobable son las cifras, las fechas, los nombres, las citas, los enlaces y las promesas. Se comprueba contra una fuente que no produjo la afirmación: el texto oficial, el archivo del proyecto, la lista de cambios, el código corriendo con el caso real.","El riesgo se mide por lo que pasa si está mal y por quién lo paga: un adorno no lo paga nadie; una ficha impresa la paga una maestra delante de sus alumnos; un correo lo paga el proyecto durante todo un año.","Casi siempre lo que no se mira es lo que no da error: los rótulos heredados, el alcance de una herramienta, lo que el resumen dejó fuera, y las comprobaciones que nunca se han visto en rojo.","La entrega se firma o no se entrega. Si algo no se pudo comprobar, se borra o se marca como no comprobado, con nombre y fecha; lo que no se puede explicar con palabras propias no sale de casa."];

const critErrorBank=[{"txt":"\"La cita viene con número de artículo y todo, así que es fiable\".","g1":"El número y las comillas son parte del estilo: una cita inventada se escribe exactamente igual de bien que una real, porque las dos son texto probable.","g2":"Solo se distinguen abriendo la fuente primaria. Y si el artículo no aparece, la cita se borra, no se deja «por si acaso» ni se sustituye por otra parecida."},{"txt":"\"Le pregunté si estaba seguro y me dijo que sí\".","g1":"Eso no es una verificación: es una segunda predicción de la misma máquina. Si inventó el dato, puede inventar igual de bien la confirmación.","g2":"Y hay algo peor: la complacencia. Si insistes, muchas veces cambia de opinión hacia lo que pareces querer oír, así que insistir aleja de la verdad en vez de acercar."},{"txt":"\"El código funcionó a la primera en mi teléfono, ya se puede subir\".","g1":"Funcionó en un caso, no en el que importa. Riesgo muy alto: lo que se sube lo usan la maestra sin internet y las niñas en el teléfono viejo.","g2":"La verificación aquí es ejecutar el caso real, no leerlo hasta que se entienda. Y en riesgo muy alto conviene que lo mire una segunda persona antes de subirlo."},{"txt":"\"El resumen está perfecto, no dice nada que no esté en el reglamento\".","g1":"Es verdad y aun así puede estar mal: el error de un resumen no está en lo que dice, está en lo que calla, y en este caso calló la fecha de cierre.","g2":"La única defensa contra una omisión es abrir el original y leer al menos los encabezados y las notas, buscando qué tendría que estar y no está."},{"txt":"\"La herramienta dice que arregló los tres bancos, todo en verde\".","g1":"El informe solo habla de lo que la herramienta vino a arreglar. No dice qué más tocó, y en este caso reescribió las veintiuna misiones del proyecto.","g2":"De una herramienta se verifica el alcance completo, no el resultado prometido. Aquí la comprobación buena era mirar la lista de archivos modificados."},{"txt":"\"El correo quedó buenísimo, lo mando ya\".","g1":"Antes hay que buscar los verbos que comprometen: acompañamos, garantizamos, entregamos, capacitamos. Cada uno es una promesa que alguien va a cobrar.","g2":"Y el compromiso lo firma quien envía. No se puede alegar después que lo escribió una máquina: para la Secretaría lo escribió el proyecto."}];

const critDecisionBank=["Un número que salió de un cálculo razonable y no de una medición: ¿cómo se comprueba y qué se hace mientras tanto?","Un molde heredado con rótulos de otra misión: ¿qué partes se revisan y cómo se evita que vuelva a pasar?","Una regla de seguridad que tiene la forma correcta: ¿cómo se lee de verdad antes de aprobarla?","Tres comprobaciones que siempre salen en verde: ¿cómo se sabe si funcionan?","Una herramienta que arregla lo que promete: ¿qué se verifica además del resultado?","Una cita de ley en una ficha que va a trescientas copias: ¿se comprueba, se borra o se marca?","Un resumen correcto de un reglamento con fechas: ¿qué se hace antes de usarlo para decidir?","Un correo a una institución con un compromiso que nadie decidió: ¿qué se quita y quién firma?"];
const critDecisionGuide="La decisión correcta sigue las reglas de la casa: quien entrega firma, así que lo primero es preguntarse si se puede explicar con palabras propias; el error que se busca no es el disparate sino el dato falso bien escrito; la comprobación se hace por fuera, contra una fuente que no produjo la afirmación, nunca preguntándole otra vez a la misma máquina; se verifica según qué pasa si está mal y a quién le pasa, no según lo raro que suene; y lo que no se pudo comprobar se borra o se marca como no comprobado, con fecha y nombre. Cuando hay prisa por entregar, la respuesta es siempre la misma: sale lo comprobado y se queda lo demás.";

const critCompareBank=[{"a":"Abrir el texto oficial y buscar el artículo citado.","b":"Preguntarle a la máquina si el artículo es correcto.","ga":"Caso A: la comprobación no depende de quien hizo la afirmación, así que puede desmentirla. Cuesta tres minutos y cierra la duda.","gb":"Caso B: se pide una segunda predicción a la misma fuente. Puede confirmar un dato inventado con total seguridad, y encima deja la sensación de haber verificado."},{"a":"Leer la respuesta entera antes de decidir qué hacer con ella.","b":"Ir corrigiendo por partes según se va leyendo.","ga":"Caso A: se ve el conjunto, y sobre todo se ve lo que falta, que es lo único que no aparece leyendo por trozos.","gb":"Caso B: se corrigen frases y se pierde la omisión, que es el error más caro y el que no está escrito en ninguna parte."},{"a":"Verificar una cifra de una ficha impresa contra la fuente primaria.","b":"Verificar con el mismo cuidado el emoji del título.","ga":"Caso A: riesgo alto, porque sale de casa impresa y lo paga una maestra delante de sus alumnos. Ahí el tiempo está bien gastado.","gb":"Caso B: riesgo cero. Verificar todo igual no es rigor: es gastar en lo barato el tiempo que hacía falta en lo caro."},{"a":"Entregar solo lo que se puede explicar con palabras propias.","b":"Entregar todo y avisar de que lo revisó una máquina.","ga":"Caso A: la firma significa algo, porque quien firma puede responder preguntas sobre lo que firmó.","gb":"Caso B: el aviso no traslada la responsabilidad a nadie. Para la maestra, para la Secretaría y para la familia, lo entregó una persona."}];

const critCauseBank=[{"cause":"Se toma el tono seguro de una respuesta como señal de que es cierta.","guide":"El tono es estilo. La máquina escribe igual de firme lo que le consta y lo que completó, porque no sabe que no sabe."},{"cause":"Se comprueba preguntándole a la misma máquina.","guide":"Se obtiene otra predicción, no una comprobación, y encima con complacencia: si insistes, cambia de opinión hacia lo que pareces querer."},{"cause":"Se verifica todo con el mismo cuidado, sin escala de riesgo.","guide":"Se gasta en lo barato el tiempo que hacía falta en lo caro, y al final no se revisa bien justo lo que sale de casa impresa."},{"cause":"Se lee la respuesta por trozos, corrigiendo sobre la marcha.","guide":"Se pierde la omisión, que es el error que no está escrito y que solo se ve mirando el conjunto contra el original."},{"cause":"Se copia un molde sin leer lo que no da error.","guide":"Los títulos, los pies y las etiquetas heredadas viajan intactos de misión en misión, porque nada avisa de que están mal."},{"cause":"Se confía en una comprobación que nunca se ha visto fallar.","guide":"No se sabe si funciona. Puede estar avisando en vez de deteniendo, y salir en verde mientras la puerta sigue abierta."}];
const critEffectBank=[{"effect":"La cita se cayó antes de imprimir las trescientas copias.","guide":"Se abrió el texto oficial en vez de preguntarle a la máquina, y el artículo no estaba. La cita se borró en lugar de dejarla por si acaso."},{"effect":"La ficha volvió a caber sin encoger la letra.","guide":"Se midió el alto útil real de la hoja en lugar de calcularlo con el margen del navegador: 252 milímetros y no 226."},{"effect":"El correo salió sin comprometer al proyecto a un año entero.","guide":"Se leyó en voz alta y se subrayaron los verbos que comprometen, y el que no se podía cumplir hoy se quitó antes de enviar."},{"effect":"Se descubrió a tiempo que la herramienta tocaba misiones que no debía.","guide":"Se miró la lista de archivos modificados y no el informe, que solo hablaba de lo que la herramienta venía a arreglar."},{"effect":"Una comprobación empezó a servir de verdad.","guide":"Se la hizo fallar a propósito una vez para ver si detenía algo. Hasta entonces salía en verde y no probaba nada."},{"effect":"La inscripción al concurso se envió dentro del plazo.","guide":"Se abrió el reglamento original en vez de fiarse del resumen, y la fecha de cierre estaba en una nota al pie."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 La firma al pie · Forma ${cf} · Verificar · Ruta de la Máquina que Predice`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La entrega sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué se puede comprobar aquí, contra qué fuente exactamente y qué riesgo tiene si está mal? Explica por qué comprobar por fuera es mejor que preguntarle otra vez a la máquina o que entregarlo tal cual.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos deja una entrega que se puede defender si alguien pregunta, y por qué? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La firma al pie: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La entrega sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué se puede comprobar aquí, contra qué fuente exactamente y qué riesgo tiene si está mal? Explica por qué comprobar por fuera es mejor que preguntarle otra vez a la máquina o que entregarlo tal cual.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos deja una entrega que se puede defender si alguien pregunta, y por qué? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La firma al pie · Verificar · Ruta de la Máquina que Predice · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La firma al pie · Verificar · Ruta de la Máquina que Predice · Etapa 3 · Inteligencia Artificial</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La firma al pie · Verificar · Ruta de la Máquina que Predice · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"📖","label":"Leer entero","text":"Hasta el final, <strong>antes de decidir nada</strong>. <strong>Sirve para:</strong> ver el conjunto y sobre todo lo que falta. <strong>Si se salta:</strong> se corrigen frases y se pierde la omisión. <strong>La prueba:</strong> poder contarlo con palabras propias."},{"y":"2","icon":"🔍","label":"Marcar lo comprobable","text":"Señalar <strong>cifras, fechas, nombres, citas, enlaces y promesas</strong>. <strong>Sirve para:</strong> separar lo que se comprueba de lo que se discute. <strong>Si se salta:</strong> se verifica al azar. <strong>En M.E.T.A.S:</strong> el lápiz sobre el papel, marca por marca."},{"y":"3","icon":"⚖️","label":"Medir el riesgo","text":"<strong>Qué pasa si esa marca está mal</strong>, y a quién le pasa. <strong>Sirve para:</strong> repartir el tiempo. <strong>Si se salta:</strong> se gasta en lo barato lo que hacía falta en lo caro. <strong>En M.E.T.A.S:</strong> una ficha impresa la paga una maestra delante de su clase."},{"y":"4","icon":"🌐","label":"Comprobar por fuera","text":"Abrir <strong>algo que no produjo la afirmación</strong>. <strong>Sirve para:</strong> que la comprobación pueda desmentir. <strong>Si se salta:</strong> se confirma un invento con otro. <strong>En M.E.T.A.S:</strong> el texto oficial, el archivo del proyecto, el código corriendo."},{"y":"5","icon":"🕳️","label":"Buscar lo que falta","text":"Volver al original a ver <strong>qué tendría que estar</strong>. <strong>Sirve para:</strong> cazar la omisión, que no está escrita. <strong>Si se salta:</strong> se entrega un resumen correcto y sin la fecha límite. <strong>En M.E.T.A.S:</strong> encabezados y notas al pie del original."},{"y":"6","icon":"✂️","label":"Corregir o borrar","text":"Lo que no se pudo comprobar <strong>sale</strong>. <strong>Sirve para:</strong> que no quede nada dudoso dentro. <strong>Si se salta:</strong> se deja «por si acaso» y acaba impreso. <strong>En M.E.T.A.S:</strong> una cita que no aparece en la fuente se borra."},{"y":"7","icon":"✍️","label":"Firmar y registrar","text":"Anotar <strong>contra qué se comprobó y quién responde</strong>. <strong>Sirve para:</strong> que la verificación exista después. <strong>Si se salta:</strong> se repite el mismo trabajo dentro de un mes. <strong>En M.E.T.A.S:</strong> la hoja de verificación, con fecha y nombre."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🌐</span><span class="ms-text"><strong>Abriste el texto oficial:</strong> el artículo existe, pero dice otra cosa y va con otro número. Tres minutos.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✍️</span><span class="ms-text"><strong>Y ahora puedes firmar:</strong> se corrige la cita, se anota contra qué se comprobó, y la ficha sale con tu nombre sin que te quite el sueño.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🤖</span><span class="ms-text"><strong>Le preguntaste si estaba seguro:</strong> dijo que sí, con la misma seguridad con la que lo había escrito.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🖨️</span><span class="ms-text"><strong>Y salieron las trescientas copias:</strong> el error lo encuentra una maestra delante de sus alumnos. No lo dijo la IA: lo firmaste tú.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"leer":{"nombre":"Leer entero","icon":"📖","estructura":{"title":"Qué es","info":"• Recorrer la respuesta <strong>hasta el final</strong> antes de decidir nada<br>• No es pasar los ojos: es poder contarla con palabras propias<br>• Es el único paso que enseña <strong>lo que falta</strong>"},"funcion":{"title":"Cómo se hace","info":"• De una sentada, sin corregir sobre la marcha<br>• En voz alta si el texto va hacia fuera: ahí se oyen las promesas<br>• Al terminar, resumirla sin mirarla; lo que no salga, no se leyó"},"enfermedades":{"title":"Qué pasa si se salta","info":"• Se corrigen frases sueltas y se pierde el conjunto<br>• La omisión pasa entera, porque no está escrita en ningún sitio<br>• Se entrega algo que no se puede defender si alguien pregunta"},"cuidados":{"title":"En este proyecto","info":"• La constancia que decía <strong>«Etapa 1»</strong> viajó por varias misiones<br>• Con ella viajaron cinco rótulos más, todos de texto de adorno<br>• Regla: <strong>copiar no es leer</strong>, y lo heredado se revisa entero"}},"riesgo":{"nombre":"Medir el riesgo","icon":"⚖️","estructura":{"title":"Qué es","info":"• Preguntarse <strong>qué pasa si esto está mal</strong>, y a quién le pasa<br>• No depende de lo raro que suene: depende de dónde va a parar<br>• Es lo que reparte el tiempo de verificación, que es limitado"},"funcion":{"title":"Cómo se hace","info":"• Bajo: adornos y redacción. Se lee entero y basta<br>• Alto: cifras, citas y leyes que se imprimen. Fuente primaria<br>• Muy alto: código que se sube y compromisos por escrito. Segunda persona"},"enfermedades":{"title":"Qué pasa si se salta","info":"• Se verifica todo igual, que es la forma elegante de no verificar nada<br>• O no se verifica nada, con el argumento de que no hay tiempo<br>• El error acaba saliendo justo por donde más caro cuesta"},"cuidados":{"title":"En este proyecto","info":"• Una ficha impresa la paga <strong>una maestra delante de su clase</strong><br>• Un correo a una institución compromete al proyecto un año<br>• Un emoji mal puesto no lo paga nadie: ahí no se gasta tiempo"}},"fuente":{"nombre":"Comprobar por fuera","icon":"🌐","estructura":{"title":"Qué es","info":"• Contrastar contra algo que <strong>no produjo la afirmación</strong><br>• Vale porque puede desmentirla; si no puede, no es una comprobación<br>• Preguntarle a la misma máquina es pedir otra predicción"},"funcion":{"title":"Cómo se hace","info":"• Citas y leyes: <strong>el texto oficial</strong>, buscando la frase textual<br>• Cifras: el estudio o el informe original, no quien lo cuenta<br>• Código: <strong>ejecutarlo con el caso real</strong>, no leerlo hasta entenderlo"},"enfermedades":{"title":"Qué pasa si se salta","info":"• Se confirma un invento con otro invento igual de bien escrito<br>• Aparece la complacencia: si insistes, cambia de opinión<br>• Queda la sensación de haber verificado, que es lo más peligroso"},"cuidados":{"title":"En este proyecto","info":"• Los <strong>226 milímetros</strong> salieron de un cálculo, no de una medición<br>• El alto real era 252 y costó dos vueltas de trabajo<br>• Con las fichas quedó escrito: <strong>el PDF es el único juez</strong>"}},"firma":{"nombre":"Firmar","icon":"✍️","estructura":{"title":"Qué es","info":"• Quien entrega, <strong>responde</strong> por lo entregado<br>• «Lo dijo la IA» no es una defensa ante nadie<br>• La máquina no tiene nada que perder; la persona sí"},"funcion":{"title":"Cómo se hace","info":"• Se anota <strong>contra qué se comprobó</strong> y qué quedó sin comprobar<br>• Con fecha y nombre, para que la verificación exista dentro de un mes<br>• Lo que no se puede explicar con palabras propias, no se entrega"},"enfermedades":{"title":"Qué pasa si se salta","info":"• Se repite el mismo trabajo, porque nadie sabe qué se revisó ya<br>• Si aparece un error, no hay forma de saber dónde falló la cadena<br>• La responsabilidad se diluye, y lo que se diluye no se corrige"},"cuidados":{"title":"En este proyecto","info":"• Cada misión lleva su <strong>sonda</strong>, y la sonda se escribe viéndola fallar<br>• Las fichas se confirman contando las hojas del PDF<br>• Lo que no se delega jamás: la firma y <strong>qué se le enseña a las niñas</strong>"}}};
let labParte='leer',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue leyendo antes de entregar!','¡Muy buen trabajo!','¡Ya distingues el dato de la opinión!','¡Compruebas por fuera y no por dentro!','¡Firmas solo lo que puedes explicar!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🔎 ¡'+name+' completó la Etapa 3 de la Ruta de la Máquina que Predice (Verificar)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

